import React from "react";
import { BrowserRouter as Router, Route, Routes } from "react-router-dom";
import Login from "./components/Login"; // Update path if needed
import SignUp from "./components/SignUp"; // Update path if needed
import MerchantDashboard from "./components/MerchantDashboard"; // Update path if needed
import PrivateRoute from "./components/PrivateRoute";
import AdminDashboard from "./components/AdminDashboard"; // Ensure this import is correct

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/login" element={<Login />} />
          <Route path="/sign-up" element={<SignUp />} />
          <Route element={<PrivateRoute role="SA" />}>
            <Route path="/admin-dashboard" element={<AdminDashboard />} />
          </Route>
          <Route element={<PrivateRoute role="M" />}>
            <Route path="/merchant-dashboard" element={<MerchantDashboard />} />
          </Route>
        </Routes>
      </div>
    </Router>
  );
}
export default App;
